/// Hellraiser (Rare, 2 energy, Power). Bead `sts2-rs-vdl`: apply
/// `PowerKind::Hellraiser(1)` to the player. Mirrors
/// `sts2-rl-agent@01c094d:sts2_env/cards/ironclad.py:1798-1799`.
///
/// C# `HellraiserPower.cs:34-42` (`AfterCardDrawnEarly`): when any
/// Strike-tagged card is drawn while HellraiserPower is active, it is
/// immediately auto-played. The Rust trigger lives in
/// `CombatState::invoke_card_drawn_for_newly_drawn` and must walk the
/// mirror+legacy power UNION (bead `sts2-rs-bsj93`).
pub(crate) fn play_hellraiser(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    apply_power_to_player(state, PowerKind::Hellraiser, 1);
    EffectResult::Resolved
}

