    /// Build a minimal state: alive player (with mirror creature), one
    /// enemy, and the full Ironclad card registry installed.
    fn state_with_enemy_and_player_mirror(enemy_hp: i32) -> (CombatState, CreatureUid) {
        crate::cards::ironclad::install_pool();
        install_default_registry();
        let mut state = CombatState {
            rng: sts2_core::dotnet_rng::Rng::new(0_i32),
            ..Default::default()
        };
        state.player.current_hp = 80;
        state.player.max_hp = 80;
        state.player.energy = 3;
        state.phase = CombatPhase::PlayerPlayPhase;

        // Enemy creature.
        let enemy_id = NonZeroU32::new(1).expect("non-zero");
        state.creatures.push(Creature {
            id: enemy_id,
            current_hp: enemy_hp,
            max_hp: enemy_hp,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Nibbit"),
            ai: None,
        });
        let enemy_uid = CreatureUid(enemy_id);
        state.enemy_uids.push(enemy_uid);

        // Player mirror creature — required so `apply_power_to_player`
        // routes through `apply_power_to_creature` (the mirror path).
        let player_id = NonZeroU32::new(100).expect("non-zero");
        state.creatures.push(Creature {
            id: player_id,
            current_hp: 80,
            max_hp: 80,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Player"),
            ai: None,
        });
        state.player.creature_uid = Some(CreatureUid(player_id));

        (state, enemy_uid)
    }

    /// Push a Strike-tagged attack card into the draw pile (top).
    /// Returns the uid. Uses `base_damage=6` matching starter Strike.
    fn push_strike_in_draw(state: &mut CombatState) -> sts2_core::CardUid {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = sts2_core::CardUid::new(raw).expect("non-zero");
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: sts2_core::CardEnergyCost::new(1),
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            combat_vars: sts2_core::cards::CombatVars::new(),
            enchantments: sts2_core::cards::CardEnchantments::new(),
            tags: CardTags::one(sts2_core::cards::CardTag::Strike),
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        });
        state.player.draw.insert(0, uid);
        uid
    }

    /// C# `Hook.AfterCardDrawn` (v0.111.0 + v0.107.1 `Hook.cs:346-361`) runs
    /// every listener's `AfterCardDrawnEarly` before any `AfterCardDrawn`.
    /// `HellraiserPower.AfterCardDrawnEarly` auto-plays the drawn Strike
    /// (awaited), so by the time `Slither.AfterCardDrawn` runs the card is no
    /// longer in hand and Slither returns on `Card.Pile.Type != PileType.Hand`
    /// (`Slither.cs`) WITHOUT a `CombatEnergyCosts` roll. Rust used to roll
    /// Slither for the whole drawn batch before the Hellraiser decision
    /// (act23 Ironclad:4092 @688: Rust one read ahead). Covers the turn-start
    /// hand draw and the card-effect draw (`draw_via_state`) paths.
    #[test]
    fn hellraiser_autoplayed_slither_strike_does_not_roll_combat_energy_costs() {
        for effect_draw in [false, true] {
            let (mut state, _enemy) = state_with_enemy_and_player_mirror(100);
            let player_cuid = state.player.creature_uid.expect("mirror set");
            apply_power_to_creature(&mut state, player_cuid, PowerKind::Hellraiser, 1);
            let strike = push_strike_in_draw(&mut state);
            state.cards[strike.get() as usize - 1]
                .enchantments
                .push((sts2_core::cards::EnchantmentId::Slither, 1));

            let before = state.run_rng.combat_energy_costs.counter();
            if effect_draw {
                sts2_core::cards::draw_via_state(&mut state, 1);
            } else {
                state.draw_into_hand(1);
            }
            assert!(
                state.player.discard.contains(&strike),
                "Strike must be auto-played (effect_draw={effect_draw})"
            );
            assert_eq!(
                state.run_rng.combat_energy_costs.counter(),
                before,
                "auto-played Slither Strike left hand before Slither's AfterCardDrawn: \
                 no roll (effect_draw={effect_draw})"
            );
        }
    }

    /// Control for the test above: a Slither card Hellraiser does NOT
    /// auto-play (no Strike tag) stays in hand and rolls exactly once.
    #[test]
    fn hellraiser_non_strike_slither_card_still_rolls_once() {
        let (mut state, _enemy) = state_with_enemy_and_player_mirror(100);
        let player_cuid = state.player.creature_uid.expect("mirror set");
        apply_power_to_creature(&mut state, player_cuid, PowerKind::Hellraiser, 1);
        let card = push_strike_in_draw(&mut state);
        {
            let c = &mut state.cards[card.get() as usize - 1];
            c.tags = CardTags::NONE;
            c.enchantments
                .push((sts2_core::cards::EnchantmentId::Slither, 1));
        }
        let before = state.run_rng.combat_energy_costs.counter();
        state.draw_into_hand(1);
        assert!(state.player.hand.contains(&card));
        assert_eq!(state.run_rng.combat_energy_costs.counter(), before + 1);
    }

    /// Bead `sts2-rs-bsj93`, base path (no upgrade):
    /// When HellraiserPower is applied via the MIRROR creature path
    /// (`player.creature_uid` set → `apply_power_to_creature`), drawing a
    /// Strike card MUST auto-play it.
    ///
    /// Root: `invoke_card_drawn_for_newly_drawn` previously walked only
    /// `self.player.powers` (the LEGACY surface). When the power is stored
    /// on the mirror creature instead, that scan returns empty → no autoplay.
    /// Fix: use `self.player_power_amount(PowerKind::Hellraiser) > 0` which
    /// walks the union (`player_power_uids` merges both surfaces).
    ///
    /// C# ref: `HellraiserPower.cs:34-42` (`AfterCardDrawnEarly`).
    #[test]
    fn bsj93_hellraiser_via_mirror_path_autoplays_strike_on_draw() {
        let (mut state, enemy_uid) = state_with_enemy_and_player_mirror(100);

        // Apply Hellraiser to player via the mirror-creature path.
        let player_cuid = state.player.creature_uid.expect("mirror set");
        apply_power_to_creature(&mut state, player_cuid, PowerKind::Hellraiser, 1);

        // Verify the power is on the mirror creature, NOT the legacy list.
        assert!(
            state.player.powers.is_empty(),
            "legacy player.powers must be empty (mirror path)"
        );
        let mirror = state
            .creatures
            .iter()
            .find(|c| c.id == player_cuid.0)
            .expect("mirror creature exists");
        assert!(
            mirror.powers.iter().any(|puid| state
                .powers
                .iter()
                .any(|p| p.id == puid.0 && p.kind == PowerKind::Hellraiser)),
            "Hellraiser must be on mirror creature"
        );

        // Push a Strike-tagged card into draw.
        let strike_uid = push_strike_in_draw(&mut state);

        let hp_before = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .expect("enemy")
            .current_hp;

        // Snapshot the CombatTargets cursor before the auto-play. C#
        // `CardCmd.AutoPlay` (CardCmd.cs:60) rolls
        // `CombatTargets.NextItem(HittableEnemies)` to pick the target,
        // consuming exactly one read even with a single hittable enemy
        // (NextInt on a 1-element range still advances). The Rust auto-play
        // must mirror this via `get_random_enemy()`; assert the cursor moves
        // by exactly one so a downstream stream desync can't slip in.
        let targets_counter_before = state.run_rng.combat_targets.counter();

        // Draw one card. invoke_card_drawn_for_newly_drawn fires and should
        // auto-play the Strike (removing it from hand to discard).
        state.draw_into_hand(1);

        let hp_after = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .expect("enemy")
            .current_hp;

        // Strike must be auto-played (removed from hand, in discard, damage dealt).
        assert!(
            !state.player.hand.contains(&strike_uid),
            "Strike must NOT remain in hand after Hellraiser auto-play"
        );
        assert!(
            state.player.discard.contains(&strike_uid),
            "Strike must be in discard after auto-play"
        );
        assert!(
            hp_after < hp_before,
            "Strike must deal damage to enemy (hp: {hp_before} → {hp_after})"
        );
        // CombatTargets cursor advanced by EXACTLY one (the target roll for
        // the single auto-played Strike). C# CardCmd.cs:60.
        assert_eq!(
            state.run_rng.combat_targets.counter(),
            targets_counter_before + 1,
            "Hellraiser auto-play must roll CombatTargets exactly once (single enemy)"
        );
    }

    /// Bead `sts2-rs-bsj93`, two-enemy targeting:
    /// With two alive enemies, the Hellraiser auto-play target is chosen by
    /// rolling `CombatTargets.NextItem` over the alive list (C#
    /// `CardCmd.cs:60`), NOT hardcoded to slot 0. Force the `combat_targets`
    /// stream into a state whose first roll over a 2-element list returns 1,
    /// and assert enemy slot 1 (not slot 0) takes the Strike damage.
    #[test]
    fn bsj93_hellraiser_two_enemies_target_from_combat_targets_roll() {
        crate::cards::ironclad::install_pool();
        install_default_registry();

        // Find a master seed whose first CombatTargets roll over 2 elements
        // is slot 1. This keeps the test hermetic (no magic seed constant)
        // while still pinning the rolled-target behaviour.
        let seed = (0_i32..10_000)
            .find(|&s| {
                let mut probe = sts2_core::run_rng_set::RunRngSet::new(s);
                probe.combat_targets.next_int_exclusive(0, 2) == 1
            })
            .expect("a seed exists whose first 2-element CombatTargets roll is slot 1");

        let mut state = CombatState {
            rng: sts2_core::dotnet_rng::Rng::new(0_i32),
            run_rng: sts2_core::run_rng_set::RunRngSet::new(seed),
            ..Default::default()
        };
        state.player.current_hp = 80;
        state.player.max_hp = 80;
        state.player.energy = 3;
        state.phase = CombatPhase::PlayerPlayPhase;

        // Two alive enemies (slots 0 and 1).
        let enemy0_id = NonZeroU32::new(1).expect("non-zero");
        state.creatures.push(Creature {
            id: enemy0_id,
            current_hp: 100,
            max_hp: 100,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Nibbit"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid(enemy0_id));
        let enemy1_id = NonZeroU32::new(2).expect("non-zero");
        state.creatures.push(Creature {
            id: enemy1_id,
            current_hp: 100,
            max_hp: 100,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Nibbit"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid(enemy1_id));

        // Player mirror creature so apply_power_to_player → mirror path.
        let player_id = NonZeroU32::new(100).expect("non-zero");
        state.creatures.push(Creature {
            id: player_id,
            current_hp: 80,
            max_hp: 80,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Player"),
            ai: None,
        });
        state.player.creature_uid = Some(CreatureUid(player_id));

        apply_power_to_creature(&mut state, CreatureUid(player_id), PowerKind::Hellraiser, 1);

        let strike_uid = push_strike_in_draw(&mut state);

        let e0_before = state.creatures[0].current_hp;
        let e1_before = state.creatures[1].current_hp;

        state.draw_into_hand(1);

        let e0_after = state.creatures[0].current_hp;
        let e1_after = state.creatures[1].current_hp;

        assert!(
            !state.player.hand.contains(&strike_uid),
            "two-enemy: Strike must NOT remain in hand"
        );
        // The rolled target was slot 1 → enemy 1 takes the damage, enemy 0 untouched.
        assert_eq!(
            e0_after, e0_before,
            "two-enemy: slot-0 enemy must be UNTOUCHED (roll picked slot 1, not hardcoded slot 0)"
        );
        assert!(
            e1_after < e1_before,
            "two-enemy: slot-1 enemy (rolled target) must take the Strike damage"
        );
    }

