    /// Bead `sts2-rs-bsj93` residual (HELLRAISER+1 quick-sweep seed 40):
    /// the TURN-START hand draw runs while `state.phase ==
    /// CombatPhase::PlayerTurnStart` (the step-11 flip to `PlayerPlayPhase`
    /// happens AFTER the draw). The old auto-play loop routed through
    /// `combat_loop::play_card`, whose phase guard returned `Advanced`
    /// (no-op) outside `PlayerPlayPhase` — so Hellraiser silently skipped
    /// every Strike drawn at turn start. C# `CardCmd.AutoPlay` has no such
    /// gate (it plays mid-draw) and is a FREE play (`EnergySpent = 0`,
    /// `CardCmd.cs:104`). The fix routes through
    /// `resolve_auto_played_card` (the Stampede pattern, `sts2-rs-lmfsm`):
    /// this test pins both properties — the auto-play fires in
    /// `PlayerTurnStart` AND spends no energy.
    #[test]
    fn bsj93_hellraiser_autoplays_on_turn_start_draw_without_energy() {
        let (mut state, enemy_uid) = state_with_enemy_and_player_mirror(100);
        // Turn-start draw phase: NOT PlayerPlayPhase.
        state.phase = CombatPhase::PlayerTurnStart;

        let player_cuid = state.player.creature_uid.expect("mirror set");
        apply_power_to_creature(&mut state, player_cuid, PowerKind::Hellraiser, 1);

        let strike_uid = push_strike_in_draw(&mut state);
        let energy_before = state.player.energy;
        let hp_before = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .expect("enemy")
            .current_hp;

        state.draw_into_hand(1);

        let hp_after = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .expect("enemy")
            .current_hp;

        assert!(
            !state.player.hand.contains(&strike_uid),
            "turn-start draw: Strike must NOT remain in hand (phase guard must not block auto-play)"
        );
        assert!(
            state.player.discard.contains(&strike_uid),
            "turn-start draw: Strike must be in discard after auto-play"
        );
        assert!(
            hp_after < hp_before,
            "turn-start draw: Strike must deal damage (hp: {hp_before} → {hp_after})"
        );
        assert_eq!(
            state.player.energy, energy_before,
            "auto-play is FREE (C# CardCmd.AutoPlay EnergySpent=0) — energy must not drain"
        );
    }

    /// act23 Ironclad:1006: Twin Strike downs TestSubject mid-draw. Its
    /// `Adaptable` corpse keeps the combat open, so C# `CardCmd.AutoPlay`
    /// passes its `IsOverOrEnding` gate, finds no hittable enemy and sends the
    /// next drawn Strike to the discard pile WITHOUT playing it
    /// (`CardCmd.cs:76-86`: no target roll, no damage). Rust used to leave
    /// every Strike drawn after the kill in hand.
    #[test]
    fn hellraiser_discards_strike_drawn_with_only_an_adaptable_corpse() {
        let (mut state, enemy_uid) = state_with_enemy_and_player_mirror(100);
        apply_power_to_creature(&mut state, enemy_uid, PowerKind::Adaptable, 1);
        state.creatures[0].current_hp = 0;
        assert!(!sts2_core::combat_loop::combat_is_ending(&state));
        let player_cuid = state.player.creature_uid.expect("mirror set");
        apply_power_to_creature(&mut state, player_cuid, PowerKind::Hellraiser, 1);
        let strike_uid = push_strike_in_draw(&mut state);
        let targets_before = state.run_rng.combat_targets.counter();

        state.draw_into_hand(1);

        assert!(
            !state.player.hand.contains(&strike_uid),
            "Strike left in hand"
        );
        assert!(
            state.player.discard.contains(&strike_uid),
            "Strike not discarded"
        );
        assert_eq!(state.creatures[0].current_hp, 0);
        assert_eq!(
            state.run_rng.combat_targets.counter(),
            targets_before,
            "NextItem over no hittable enemy reads no RNG"
        );
    }
